#[cfg(any(test, kani))]
pub fn allowed_event(pre: AState, op: AbstractOp, outcome: AbstractOutcome, post: AState) -> bool {
    let Some(pre) = pre.domain_index() else {
        return false;
    };
    let Some(post) = post.domain_index() else {
        return false;
    };
    let index =
        ((pre * OP_COUNT + op as usize) * OUTCOME_COUNT + outcome as usize) * STATE_COUNT + post;
    ALLOWED_BITS[index / 8] & (1 << (index % 8)) != 0
}

